// Generated by Dartform: read-only rows for the project's dashboard.
// Rewritten when the dashboard's tables change.

import 'dart:convert';

import 'package:serverpod/serverpod.dart';

class DashboardEndpoint extends Endpoint {
  static const _tables = {'company', 'employee'};
  static const _maxRows = 5000;

  /// Up to 5000 rows of [table] as JSON: `{"rows": [...], "more": true}`
  /// when there are more, or `{"error": "..."}`. Outside development, [key]
  /// must match the `dashboardKey` password.
  Future<String> rows(Session session, String key, String table) async {
    final refused = _checkKey(session, key);
    if (refused != null) return jsonEncode({'error': refused});
    if (!_tables.contains(table)) {
      return jsonEncode({'error': 'Not a dashboard table.'});
    }
    final result = await session.db
        .unsafeQuery('SELECT * FROM "$table" LIMIT ${_maxRows + 1}');
    final rows = [for (final row in result) row.toColumnMap()];
    return jsonEncode({
      'rows': _json(rows.take(_maxRows).toList()),
      'more': rows.length > _maxRows,
    });
  }

  String? _checkKey(Session session, String key) {
    if (session.serverpod.runMode == ServerpodRunMode.development) {
      return null;
    }
    final expected = session.passwords['dashboardKey'] ?? '';
    if (expected.isEmpty) return 'dashboardKey is not set on the server.';
    if (!_sameText(key, expected)) return 'Missing or wrong dashboard key.';
    return null;
  }
}

/// Values Postgres returns that JSON can't hold directly (dates, UUIDs)
/// become strings.
Object? _json(Object? value) => switch (value) {
      null || bool() || num() || String() => value,
      DateTime() => value.toUtc().toIso8601String(),
      List() => value.map(_json).toList(),
      Map() => value.map((k, v) => MapEntry('$k', _json(v))),
      _ => value.toString(),
    };

/// Compares in constant time, so response timing doesn't reveal the key.
bool _sameText(String a, String b) {
  if (a.length != b.length) return false;
  var difference = 0;
  for (var i = 0; i < a.length; i++) {
    difference |= a.codeUnitAt(i) ^ b.codeUnitAt(i);
  }
  return difference == 0;
}
